const raw = $input.first().json;
const expected = $env.ANSER_WEBHOOK_TOKEN || '';
if (expected && ((raw.headers || {})['x-anser-token'] || '') !== expected) {
  return [{ json: { valid: false, error: 'Unauthorized' } }];
}
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const channel = (b.channel || '').toLowerCase();
// CHUẨN HÓA payload từng kênh về schema chung (PDF A1 bước 1)
let ext, items, customer;
try {
  if (channel === 'shopee') {
    ext = 'SHOPEE-' + b.order_sn;
    items = (b.item_list || []).map(i => ({ sku: i.item_sku, name: i.item_name || i.item_sku, qty: i.model_quantity_purchased || 1, price: parseFloat(i.model_discounted_price || 0) }));
    customer = (b.recipient_address || {}).name || null;
  } else if (channel === 'tiktok') {
    ext = 'TIKTOK-' + b.order_id;
    items = (b.line_items || []).map(i => ({ sku: i.seller_sku, name: i.product_name || i.seller_sku, qty: i.quantity || 1, price: parseFloat(i.sale_price || 0) }));
    customer = (b.recipient_address || {}).name || null;
  } else if (channel === 'web') {
    ext = 'WOO-' + b.id;
    items = (b.line_items || []).map(i => ({ sku: i.sku, name: i.name || i.sku, qty: i.quantity || 1, price: parseFloat(i.price || 0) }));
    customer = ((b.billing || {}).first_name ? ((b.billing.first_name + ' ' + (b.billing.last_name || '')).trim()) : null);
  } else {
    return [{ json: { valid: false, error: 'channel không hỗ trợ: ' + channel + ' (web|shopee|tiktok)' } }];
  }
} catch (e) {
  return [{ json: { valid: false, error: 'payload kênh ' + channel + ' không đúng shape: ' + e.message } }];
}
if (!ext || !items || !items.length) return [{ json: { valid: false, error: 'Thiếu mã đơn kênh hoặc items' } }];
return [{ json: { valid: true, channel, request_body: JSON.stringify({ channel, external_order_id: ext, customer_name: customer, is_gift: b.is_gift === true, items }) } }];

// Đồng bộ tồn MỚI ngược lên TẤT CẢ kênh (PDF A1 bước 3 — bán 1 kênh, giảm tồn mọi kênh)
const d = $input.first().json;
const stock_body = JSON.stringify({ event: 'stock_update', source_order: d.order_no, stock: d.new_stock });
const fmt = n => new Intl.NumberFormat('vi-VN').format(n);
const lines = (d.allocations || []).map(a => `• ${a.sku}: lô **${a.lot_code}** (HSD ${a.expiry_date}) ×${a.qty}`).join('\n');
let desc = 'Đơn ' + d.channel.toUpperCase() + ' — trừ tồn theo lô FEFO' + (d.is_gift ? ' (QUÀ TẶNG → gán lô HSD xa)' : ' (lô cận hạn xuất trước)') + ':\n' + lines;
if (d.warn_expiry) desc += '\n⚠️ Quà tặng nhưng chỉ còn lô cận hạn (<90 ngày) — cân nhắc đổi lô.';
desc += '\nTồn mới đã đẩy ngược lên web + Shopee + TikTok.';
const notify_body = JSON.stringify({ channel: 'discord', title: '🛒 Đơn đa kênh ' + d.order_no + ' (' + d.channel + ') — ' + fmt(d.total_amount) + ' đ', color: d.warn_expiry ? 15105570 : 3066993, description: desc });
const resp = JSON.stringify({ status: 'allocated', order_no: d.order_no, channel: d.channel, total_amount: d.total_amount, allocations: d.allocations, new_stock: d.new_stock, warn_expiry: d.warn_expiry });
return [{ json: { stock_body, notify_body, resp } }];

const d = $input.first().json;
const dup = d.action === 'duplicate';
const notify_body = JSON.stringify({ channel: 'discord', title: dup ? '🔁 Đơn kênh trùng (bỏ qua)' : '🔴 CHẶN OVERSELL — ' + (d.sku || ''), color: dup ? 10197915 : 15158332, description: dup ? ('Webhook kênh gửi lại — đơn đã có: ' + (d.order_no || '')) : ('Đơn cần ' + d.need + ' nhưng tồn theo lô chỉ còn ' + d.available + ' — TỪ CHỐI, không trừ gì (tránh bán trùng lô cuối giữa 2 kênh). Đồng bộ tồn/khuyến mãi lại ngay.') });
return [{ json: { notify_needed: !dup, notify_body, resp: JSON.stringify(d), code: dup ? 200 : 409 } }];
